CREATE TYPE commerce."CommercialOfferingType" AS ENUM ('QUALIFICATION_PACKAGE','REPURCHASE_PLAN','CORE_PRODUCT','RETAIL_PRODUCT','PROMOTIONAL_BUNDLE');
CREATE TABLE commerce.commercial_offering (commercial_offering_id uuid PRIMARY KEY,offering_code text NOT NULL UNIQUE,offering_type commerce."CommercialOfferingType" NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz(6) NOT NULL DEFAULT now());
CREATE INDEX commercial_offering_type_status_idx ON commerce.commercial_offering(offering_type,status);
CREATE TABLE commerce.commercial_offering_version (commercial_offering_version_id uuid PRIMARY KEY,commercial_offering_id uuid NOT NULL REFERENCES commerce.commercial_offering(commercial_offering_id),version integer NOT NULL,status text NOT NULL,effective_from timestamptz(6) NOT NULL,effective_to timestamptz(6),channels jsonb NOT NULL DEFAULT '[]'::jsonb,composition jsonb NOT NULL DEFAULT '[]'::jsonb,selection_rule jsonb,recognition_profile jsonb,approval_reference text NOT NULL,snapshot_hash char(64) NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),UNIQUE(commercial_offering_id,version),CHECK(effective_to IS NULL OR effective_to>effective_from));
CREATE INDEX commercial_offering_version_effective_idx ON commerce.commercial_offering_version(status,effective_from,effective_to);
ALTER TABLE commerce.order_line ADD COLUMN commercial_offering_version_id uuid,ADD COLUMN commercial_offering_snapshot jsonb,ADD COLUMN line_purpose text;
ALTER TABLE commerce.order_line ADD CONSTRAINT order_line_offering_version_fk FOREIGN KEY(commercial_offering_version_id) REFERENCES commerce.commercial_offering_version(commercial_offering_version_id);
